sys_variable_value.value:
(function execute(inputs, outputs) {
// Specify the source record table and the target record table
var sourceTable = 'sn_ap_cm_ap_case';  // Source table (e.g., 'incident')
var targetTable1 = 'sn_ap_ic_invoice_stage';      // Target table (e.g., 'task')
var targetTable2 = 'sys_di_task'; 
var sourceRecordSysId = inputs.invoice_case_record; // Replace with the source record Sys ID
var targetRecordSysId1 = inputs.invstage_id; // Replace with the target record Sys ID
var targetRecordSysId2 = inputs.doctask_id; 

GlideSysAttachment.copy(sourceTable, sourceRecordSysId, targetTable1, targetRecordSysId1);
GlideSysAttachment.copy(sourceTable, sourceRecordSysId, targetTable2, targetRecordSysId2);

})(inputs, outputs);

